entries.commands:
! ===== 创建 VLAN 并划入端口（Cisco IOS）=====
enable
configure terminal
vlan {{vlan_id}}
 name {{vlan_name}}
 exit
interface range {{port_range}}
 switchport mode access
 switchport access vlan {{vlan_id}}
 no shutdown
 exit
end
write memory

entries.rollback:
! 回退：逐条删除本变更新增的静态路由（含浮动备份与默认路由）
enable
configure terminal
no ip route {{dest_net}} {{mask}} {{next_hop}}
no ip route {{dest_net}} {{mask}} {{backup_hop}} 200
no ip route 0.0.0.0 0.0.0.0 {{next_hop}}
end
write memory
! 复核：路由表恢复变更前状态
show ip route {{dest_net}}

entries.commands:
! ===== OSPF 基本配置（Cisco IOS）=====
enable
configure terminal
router ospf {{process_id}}
 router-id {{router_id}}
 network {{network}} {{wildcard}} area {{area_id}}
 passive-interface default
 no passive-interface {{uplink_port}}
 exit
end
write memory
show ip ospf neighbor
show ip route ospf

! ===== NAT / PAT 配置（Cisco IOS）=====
enable
configure terminal
interface {{inside_port}}
 ip address {{inside_ip}} {{inside_mask}}
 ip nat inside
 exit
interface {{outside_port}}
 ip address {{outside_ip}} {{outside_mask}}
 ip nat outside
 exit
access-list {{acl_number}} permit {{src_net}} {{src_wild}}
ip nat inside source list {{acl_number}} interface {{outside_port}} overload
! 静态一对一映射（外网访问内网服务器）
ip nat inside source static {{inside_server}} {{public_ip}}
end
write memory
show ip nat translations
show ip nat statistics

! ===== SNMP 配置（Cisco IOS）=====
enable
configure terminal
snmp-server community {{ro_community}} RO
snmp-server community {{rw_community}} RW
snmp-server location {{location}}
snmp-server contact {{contact}}
snmp-server host {{nms_ip}} version 2c {{ro_community}}
snmp-server enable traps
! ---- 更安全的 SNMPv3（推荐生产使用，按需启用）----
snmp-server group {{v3_group}} v3 auth
snmp-server user {{v3_user}} {{v3_group}} v3 auth sha {{v3_auth_pass}} priv aes 128 {{v3_priv_pass}}
snmp-server host {{nms_ip}} version 3 auth {{v3_user}}
end
write memory
show snmp community

entries.rollback:
! 回退：删除本变更新增的 SNMP 配置（location/contact 若有旧值按变更记录恢复）
enable
configure terminal
no snmp-server host {{nms_ip}} version 2c {{ro_community}}
no snmp-server host {{nms_ip}} version 3 auth {{v3_user}}
no snmp-server user {{v3_user}} {{v3_group}}
no snmp-server group {{v3_group}} v3 auth
no snmp-server community {{ro_community}}
no snmp-server community {{rw_community}}
no snmp-server location
no snmp-server contact
end
write memory
! 复核
show snmp community
